<?php
 namespace QQWorld\Sales\Setup; use QQWorld\Framework\DB\DataConverter\DataConversionException; use QQWorld\Framework\DB\DataConverter\SerializedToJson; class SalesOrderPaymentDataConverter extends SerializedToJson { public function convert($value) { if ($this->isValidJsonValue($value)) { return $value; } $unserializedValue = $this->unserializeValue($value); if (isset($unserializedValue['token_metadata'])) { $unserializedValue['customer_id'] = $unserializedValue['token_metadata']['customer_id']; $unserializedValue['public_hash'] = $unserializedValue['token_metadata']['public_hash']; unset($unserializedValue['token_metadata']); } return $this->encodeJson($unserializedValue); } } 